#include <stdio.h>

int main() {
    int n;
    double max_venta = 0.0;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        double venta;
        scanf("%lf", &venta);
        if (venta > max_venta) {
            max_venta = venta;
        }
    }
    printf("%.1f\n", max_venta);
    return 0;
}

